{
  "positionId": "P07",
  "interviews": [
    {
      "categoryId": "P07-C2",
      "itemId": "P07-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "입사 서류 처리 중 필요한 자료가 빠지지 않았는지 스스로 점검하는 행동을 검증한다. 질문은 4대보험 취득 신고 자료 준비 보조 범위에서 실제로 수행한 누락 확인 방식에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "입사자의 4대보험 취득 신고 자료 준비를 보조하며 제출 자료를 확인해야 했던 상황이다.",
          "task": "본인이 맡은 범위에서 필요한 자료나 기재 항목이 빠지지 않았는지 확인하는 것이다.",
          "action": "담당자의 안내나 신고에 필요한 항목을 기준으로 수집한 자료를 대조하고, 미제출 자료나 빈 항목을 구별한 실제 확인 행동을 설명한다.",
          "result": "그 확인으로 자료의 구비 상태를 파악했거나 누락을 발견한 결과가 드러난다. 누락이 없었다면 무엇을 대조하여 이를 확인했는지 제시할 수 있다."
        },
        "expectedEvidence": [
          "제출 자료의 누락 여부를 확인하기 위해 본인이 실제로 수행한 점검 방식",
          "필요한 자료나 기재 항목을 판단할 때 대조한 기준",
          "점검 대상과 확인 결과를 보여 주는 구체적인 사례"
        ]
      },
      "question": "소담식품에서 4대보험 취득 신고 자료 준비를 보조하셨던데요, 그때 제출할 자료의 누락 여부를 실제로 어떤 방식으로 확인하셨어요?",
      "answerTip": "직접 맡았던 한 장면을 떠올려 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "본인의 보조 업무 범위 안에서 실제로 수행한 누락 점검 방식을 구체적으로 설명한다.",
            "필요한 자료나 기재 항목의 기준과 수집 자료를 대조한 행동이 명확하다.",
            "누락 발견 또는 자료 구비 확인 사례를 통해 점검 결과를 보여 준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "본인이 자료의 누락 여부를 확인한 행동은 드러나지만 대조 기준이나 점검 대상이 일부 불명확하다.",
            "확인 방식은 설명하나 실제 확인 결과에 대한 구체적인 사례가 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "자료를 모았거나 체크리스트를 만들었다는 설명만 있고 실제 누락 확인 행동은 드러나지 않는다.",
            "다른 담당자의 업무만 설명하거나 필요한 자료를 무엇과 대조했는지 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P07-C2",
      "itemId": "P07-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "근태 기록이 일치하지 않을 때 근거 자료를 확인하여 급여에 반영할 근로시간을 판단할 수 있는지 검증한다. 질문은 연장근로수당에 반영할 시간을 정하는 근거 하나에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "급여 지급 전 확인 과정에서 출퇴근 기록과 연장근로 승인 내역의 시간이 서로 다른 상황이다.",
          "task": "서로 다른 기록 중 하나를 그대로 택하지 않고 연장근로수당에 반영할 시간을 판단하는 것이다.",
          "action": "출퇴근 기록과 승인 내역을 실제 업무 수행을 확인할 수 있는 자료에 대조하고, 사용자의 지시나 인지 여부와 휴게시간 등을 확인하여 실제 근로시간을 판단한다.",
          "result": "불일치한 기록을 그대로 급여에 적용하지 않고 확인된 실제 근로시간에 근거해 반영할 시간을 정할 수 있다. 가정 상황이므로 실제 정산 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "연장근로수당에 반영할 시간을 정하기 위해 사용할 구체적인 근거",
          "출퇴근 기록과 승인 내역만으로 실제 연장근로시간을 단정하지 않는 판단",
          "실제 업무 수행과 사용자의 지시 또는 인지 여부, 휴게시간 등 근로시간 판단에 필요한 조건을 확인하려는 설명"
        ]
      },
      "question": "급여 지급 전 출퇴근 기록과 연장근로 승인 내역의 시간이 서로 다르다고 해 볼게요. 그럴 때 연장근로수당에 반영할 시간을 어떤 근거로 정하시겠어요?",
      "answerTip": "가정된 상황에서 본인의 생각을 차분히 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 업무 수행을 확인할 자료를 구체적으로 제시하고, 그 자료가 반영 시간 판단에 필요한 이유를 설명한다.",
            "출퇴근 기록이나 승인 내역 중 하나를 기계적으로 선택하지 않으며, 승인 누락만으로 실제 근로를 배제하지 않는다.",
            "사용자의 지시 또는 인지 여부와 휴게시간 등 관련 조건에 비추어 실제 근로시간을 확인한 뒤 반영 시간을 정하겠다고 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "기록 불일치를 인식하고 추가 자료나 사실 확인에 근거해 반영 시간을 정하겠다고 설명한다.",
            "다만 확인할 자료가 포괄적이거나 실제 근로시간을 판단하는 조건에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "불일치 원인을 확인하지 않고 출퇴근 기록 또는 승인 내역 중 하나를 그대로 적용한다.",
            "실제 업무 수행 여부와 무관하게 승인되지 않은 시간은 모두 제외하거나 체류시간을 모두 근로시간으로 간주한다.",
            "정확히 계산하겠다는 원론적인 답변만 있고 반영 시간을 판단할 근거가 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P20",
  "interviews": [
    {
      "categoryId": "P20-C1",
      "itemId": "P20-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "확인한 고객 상황을 고객이 이해할 수 있는 정확한 채팅 안내로 전달하는지 검증한다. 질문의 초점은 배송 조회 문의에서 실제로 보낸 안내 내용이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "마루커머스에서 채널톡으로 배송 조회 문의를 받은 구체적인 상담 장면이다.",
          "task": "확인된 배송 상황과 고객의 요청에 맞는 안내를 이해하기 쉬운 문장으로 전달해야 했다.",
          "action": "확인된 사실을 중심으로 고객의 궁금증에 직접 답하고, 불확실한 내용을 단정하지 않는 안내 문구를 보냈다.",
          "result": "안내 문구에서 고객이 현재 배송 상황을 이해할 수 있는 내용이 확인된다. 이후 고객 반응을 기억한다면 보조 근거로 활용하되, 재문의 감소 실적은 요구하지 않는다."
        },
        "expectedEvidence": [
          "배송 조회 문의에 실제로 보낸 안내 문구 또는 그에 준하는 구체적인 내용",
          "안내 내용이 당시 확인된 배송 사실과 고객의 요청에 맞았다는 설명",
          "고객이 이해하기 쉬운 표현을 사용하고, 확인되지 않은 배송 일정 등을 확정적으로 안내하지 않은 근거"
        ]
      },
      "question": "마루커머스에서 채널톡으로 배송 조회 문의에 응대하셨던데요, 고객이 상황을 이해할 수 있도록 보낸 안내 문구는 어떤 내용이었어요?",
      "answerTip": "기억나는 한 장면을 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 안내 문구나 이에 준하는 내용을 구체적으로 재현하며, 고객의 배송 문의에 직접 답한다.",
            "안내가 확인된 배송 사실에 근거하고, 불확실한 사항을 단정하지 않았음이 드러난다.",
            "고객이 현재 상황을 이해할 수 있도록 쉬운 표현으로 전달한 점이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "배송 상황을 안내한 핵심 내용은 확인되지만 실제 표현이나 당시 상황의 구체성이 부족하다.",
            "고객 요청에 맞게 안내한 점은 드러나지만, 확인된 사실과 안내 내용의 연결이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "친절하게 안내했다는 설명에 그쳐 실제 안내 내용을 확인할 수 없다.",
            "고객의 배송 문의와 무관한 내용을 답하거나, 확인하지 않은 정보를 확정적으로 전달한다."
          ]
        }
      }
    },
    {
      "categoryId": "P20-C1",
      "itemId": "P20-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "직접 환불을 승인할 수 없는 상황에서 정책과 처리 권한을 벗어나지 않으면서 고객에게 실행 가능한 처리 대안을 제시했는지 검증한다. 질문의 초점은 불만 고객에게 실제로 제시한 다음 조치이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "마루커머스에서 배송 지연으로 화난 고객이 환불을 요구했고, 본인은 환불을 결정할 수 없었던 상황이다.",
          "task": "환불 승인을 임의로 약속하지 않고 본인의 권한 안에서 가능한 처리 경로를 고객에게 제시해야 했다.",
          "action": "정책과 권한 범위에 맞춰 담당자 확인이나 인계 등 실행 가능한 다음 조치를 고객에게 차분하게 제시했다.",
          "result": "고객이 환불 요청이 어떤 후속 조치로 이어지는지 알 수 있는 대안이 제시되었다. 고객 반응이나 이후 진행은 기억하는 범위에서 보조 근거로 활용하며, 본인의 환불 승인 실적은 요구하지 않는다."
        },
        "expectedEvidence": [
          "배송 지연으로 환불을 요구한 고객에게 실제로 제시한 처리 대안",
          "그 대안이 확인한 정책과 본인의 처리 권한에 맞았다는 설명",
          "승인되지 않은 환불을 약속하지 않으면서 고객이 다음 조치를 알 수 있도록 침착하게 전달한 내용"
        ]
      },
      "question": "마루커머스에서 배송 지연으로 화난 고객이 환불을 요구한 적이 있으셨던데요, 그때 고객에게 제시한 처리 대안은 무엇이었어요?",
      "answerTip": "당시 있었던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당자 확인이나 인계 등 고객에게 실제로 제시한 다음 조치가 구체적이다.",
            "제시한 대안이 확인한 정책과 본인의 권한 범위에 부합하며, 임의의 환불 승인이나 확약을 하지 않았다.",
            "고객이 후속 처리를 예상할 수 있도록 차분하게 전달한 내용이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "본인의 권한을 벗어나지 않는 처리 대안은 제시했으나, 고객에게 전달한 내용이 구체적이지 않다.",
            "담당자에게 연결하는 등 가능한 처리 경로는 드러나지만, 정책이나 권한 범위와의 연결 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "고객을 진정시켰다는 설명만 있고 실제 제시한 처리 대안을 확인할 수 없다.",
            "권한 없이 환불을 약속하거나, 처리 경로 없이 불가하다는 말만 반복한다."
          ]
        }
      }
    }
  ]
}
